  const fmtConv = (t) => { const d = new Date(t), n = new Date(); if (d.toDateString() === n.toDateString()) return fmtTime(t); const diff = (n - d) / 864e5; if (diff < 6) return d.toLocaleDateString(undefined, { weekday: "short" }); return d.toLocaleDateString(undefined, { month: "short", day: "numeric" }); };
  const dayLabel = (t) => { const d = new Date(t), n = new Date(); if (d.toDateString() === n.toDateString()) return "Today"; const y = new Date(n); y.setDate(n.getDate() - 1); if (d.toDateString() === y.toDateString()) return "Yesterday"; return d.toLocaleDateString(undefined, { weekday: "long", month: "long", day: "numeric" }); };
  const PLAN_NAME = "Corporate Music Club";

