      liveComm: true, liveAccess: "everyone", requireRing: false, musicDuring: "play", duckOn: true, duckDepth: 0.7, shareBg: true, callMusic: "mine", ringBefore: true, ringtone: "classic", awayAfter: 10, heardOver: ["company", "contacts"], micVox: true, handsFree: false,
