  S.downloads = new Set(TRACK_IDS.filter((_, i) => i % 31 === 7).slice(0, 3)); S.recent = TRACK_IDS.filter((_, i) => i % 17 === 5).slice(0, 6);
  S.myPlaylists = [{ id: "pl-mine-1", name: "Bergen Boarding Mix", description: "Made by you — for the inaugural flight.", cover: D.music.playlists[0].cover, trackIds: TRACK_IDS.filter((_, i) => i % 13 === 2).slice(0, 8) }];
  D.music.playlists.forEach((p, i) => { S.points[p.id] = 3 + ((i * 7) % 11); S.comments[p.id] = []; });
  const favsOf = (pid) => { let x = 0; for (const c of pid) x = (x * 31 + c.charCodeAt(0)) % 9973; const n = 2 + (x % 4); return Array.from({ length: n }, (_, k) => tracksById[TRACK_IDS[(x * (k + 3) + k * 17) % TRACK_IDS.length]]); };

  // ---------------- UI helpers ----------------
  let toastT = null;
