      const ov = h('<div class="call-overlay" id="callOv"><div class="call-card"><div class="big">DD</div><div class="nm">Digital Demonstrator</div><div class="st">Incoming voice call · Kitaak</div><div class="muted" style="font-size:13px;margin-bottom:16px">Answer to hear the message. Your music ducks while the call is live and readjusts to its normal volume when the message is over.</div><div class="btns"><button class="btn danger" id="declineBtn">' + icon("phoneoff", 18) + ' Decline</button><button class="btn green" id="answerBtn">' + icon("phone", 18) + " Answer</button></div></div></div>");
