  // contact signs — voice-over priority is not part of the web demo
  const SIGNS = [["live", "Live Instant Communication", "livevoice"], ["chat", "Chat", "chat"], ["phone", "Phone", "phone"], ["video", "Video", "video"]];
  const SIGN_DESC = "The signs next to a contact decide how that person may reach you: the live-voice sign grants Live Instant Communication — they reach you live during the hours you allow; chat, phone and video allow messages and calls. Tap a sign to give or remove it; right-click it for the hours during which it applies. Signs marked with a small person show the contact's own stance toward you (display only).";
  function signState(id) { return S.signs[id] || (S.signs[id] = { live: false, chat: true, phone: true, video: true }); }
  function profilePopup(p) {
    if (!p || p.id === "allison") { location.hash = "#/profile"; return; }
    const sg = signState(p.id); const local = (() => { try { return new Date().toLocaleTimeString(undefined, { timeZone: p.timezone, hour: "2-digit", minute: "2-digit" }); } catch (e) { return ""; } })();
    const m = modal(p.name, '<div style="display:flex;gap:14px;align-items:center">' + avatar(p, 64, true) + '<div><div class="display" style="font-size:20px">' + esc(p.name) + '</div><div class="muted">' + esc(p.title || "") + (p.department ? " · " + esc(p.department) : "") + '</div><div class="mono muted" style="font-size:12px">' + esc(p.oNumber || "") + (p.city ? " · " + esc(p.city) : "") + (local ? " · local time " + local : "") + "</div></div></div>" + (p.bio ? '<p class="muted" style="margin:12px 0 0">' + esc(p.bio) + "</p>" : "") + (p.id === "demonstrator" ? "" : '<div class="kx-block"><div class="kx-h">Signs for ' + esc(p.name.split(" ")[0]) + ' <span data-vo></span></div><div style="display:flex;gap:4px;flex-wrap:wrap">' + SIGNS.map(([k, label, ic]) => '<button class="icon-btn ' + (sg[k] ? "on" : "") + '" data-sign="' + k + '" title="' + esc(label) + '">' + icon(ic, 18) + "</button>").join("") + '</div><div class="muted" style="font-size:12px">Right-click a sign for its hours.</div></div><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px"><button class="btn sm primary" id="ppMsg">Message</button><button class="btn sm" id="ppCall">Call</button><button class="btn sm" id="ppAdd">' + (S.contacts.has(p.id) ? "Remove contact" : "Add contact") + '</button><button class="btn sm ghost danger" id="ppBlock">' + (S.blocked.has(p.id) ? "Unblock" : "Block") + "</button></div>"), []);
    const vo = $("[data-vo]", m); if (vo) vo.appendChild(infoI(SIGN_DESC));
    $$("[data-sign]", m).forEach((b) => { b.onclick = () => { sg[b.dataset.sign] = !sg[b.dataset.sign]; b.classList.toggle("on", sg[b.dataset.sign]); toast(b.title + (sg[b.dataset.sign] ? " given" : " removed") + " for " + p.name); }; b.oncontextmenu = (e) => { e.preventDefault(); hoursPopover(e.clientX, e.clientY, p, b.title); }; });
    const mb = $("#ppMsg", m); if (mb) mb.onclick = () => { closeModal(); openDm(p.id); }; const cb = $("#ppCall", m); if (cb) cb.onclick = () => { closeModal(); openDm(p.id); setTimeout(() => simCall(room("dm:" + p.id), "voice"), 200); };
    const ab = $("#ppAdd", m); if (ab) ab.onclick = () => { if (S.contacts.has(p.id)) S.contacts.delete(p.id); else S.contacts.add(p.id); closeModal(); toast(S.contacts.has(p.id) ? p.name + " added to your contacts" : p.name + " removed from your contacts"); if (page === "contacts") renderContacts(""); };
    const bb = $("#ppBlock", m); if (bb) bb.onclick = () => { if (S.blocked.has(p.id)) S.blocked.delete(p.id); else S.blocked.add(p.id); closeModal(); toast(S.blocked.has(p.id) ? p.name + " blocked — no calls, no live voice, no messages (demo)" : p.name + " unblocked"); };
  }
  function hoursPopover(x, y, p, sign) {
    const hr = S.hours[p.id + sign] || (S.hours[p.id + sign] = { from: "09:00", to: "17:00", days: [1, 2, 3, 4, 5] });
    const pp = popover(x, y, '<b>' + esc(p.name) + " — " + esc(sign) + ' hours</b><div class="muted">This sign only works from this contact inside this window.</div><div class="row">From <input class="input" style="width:80px" data-h="from" value="' + hr.from + '"> to <input class="input" style="width:80px" data-h="to" value="' + hr.to + '"></div><div class="row">' + ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map((d, i) => '<button class="chip ' + (hr.days.includes(i) ? "on" : "") + '" data-d="' + i + '">' + d + "</button>").join("") + '</div><div class="row" style="justify-content:space-between;align-items:center"><span><button class="chip on" data-set>Set</button> <button class="chip" data-clear>Clear</button></span><span data-info></span></div>');
    $("[data-info]", pp).appendChild(infoI(SIGN_DESC));
    $$("[data-d]", pp).forEach((b) => (b.onclick = () => { const d = Number(b.dataset.d); hr.days = hr.days.includes(d) ? hr.days.filter((x) => x !== d) : hr.days.concat([d]); b.classList.toggle("on"); }));
    $("[data-set]", pp).onclick = () => { hr.from = $('[data-h="from"]', pp).value; hr.to = $('[data-h="to"]', pp).value; closePop(); toast("Hours set for " + sign + " (demo)"); }; $("[data-clear]", pp).onclick = () => { delete S.hours[p.id + sign]; closePop(); toast("Hours cleared"); };
  }
  function openDm(pid) { let r = room("dm:" + pid); if (!r) { r = { id: "dm:" + pid, type: "dm", personId: pid, name: nameOf(pid), messages: [], disappearing: "off" }; S.rooms.push(r); } location.hash = "#/chat/" + encodeURIComponent(r.id); }

  // ---------------- CONTACTS ----------------
  function renderContacts(q) {
    const main = $("#main"); const all = S.people.slice().sort((a, b) => a.name.localeCompare(b.name));
    main.innerHTML = '<div class="page-pad page-wide"><div class="eyebrow">Directory</div><h1 class="display" style="font-size:34px;margin:0 0 12px">Contacts</h1><div class="contacts-note">The <b>live-voice sign</b> next to a contact grants that contact <b>Live Instant Communication</b> — they reach you live during the hours you allow, even outside your usual availability. Signs marked with a small <b>person</b> show the contact\'s own stance toward you (display only — hover them to read it). Right-click a sign to set the hours during which it applies.</div><input class="input" id="cq" placeholder="Search people to add or message" value="' + esc(q) + '" style="max-width:520px;margin-bottom:18px"><div id="cres"></div><div class="section-head"><h3 style="margin:0">My contacts</h3><span class="muted" style="font-size:12px" id="ccount"></span></div><div id="clist"></div><div class="section-head"><h3 style="margin:0">Rooms</h3></div><div class="contact-row" style="cursor:default"><span class="avatar" style="width:48px;height:48px">CL</span><div><div class="nm">Company Lobby</div><div class="sub">An open room for ' + esc(D.company.name) + ". Say hi 👋</div></div><div></div></div></div>";
    const rowH = (p, inList) => { const sg = signState(p.id); return '<div class="contact-row" data-cid="' + esc(p.id) + '">' + avatar(p, 48, true) + '<div><div class="nm">' + esc(p.name) + (S.blocked.has(p.id) ? ' <span class="chip" style="font-size:10px">blocked</span>' : "") + '</div><div class="sub">' + esc(p.title || "") + " · " + esc(p.department || "") + " · " + esc(p.oNumber || "") + " · " + esc(p.status) + '</div></div><div class="acts">' + (inList ? SIGNS.map(([k, label, ic]) => '<button class="icon-btn ' + (sg[k] ? "on" : "") + '" data-sign="' + k + '" title="' + esc(label) + '">' + icon(ic, 18) + "</button>").join("") + '<button class="icon-btn" data-msg title="Message">' + icon("send", 18) + '</button><button class="icon-btn" data-add title="Add to group">' + icon("plus", 18) + '</button><button class="icon-btn" data-rm title="Remove contact">' + icon("trash", 18) + "</button>" : '<button class="btn sm primary" data-addc>Add</button><button class="btn sm" data-msg>Message</button>') + "</div></div>"; };
    const paint = () => { const qq = ($("#cq").value || "").trim().toLowerCase(); const mine = all.filter((p) => S.contacts.has(p.id)); const found = qq ? all.filter((p) => (p.name + " " + p.title + " " + p.department).toLowerCase().includes(qq)) : []; $("#cres").innerHTML = qq ? '<div class="section-head" style="margin-top:0"><h3 style="margin:0">Search results</h3></div>' + (found.map((p) => rowH(p, S.contacts.has(p.id))).join("") || '<div class="muted">No one matches.</div>') : ""; $("#clist").innerHTML = mine.filter((p) => !qq || found.includes(p)).map((p) => rowH(p, true)).join("") || '<div class="muted" style="padding:16px 0">No contacts yet. Search above and tap <b>Add</b>.</div>'; $("#ccount").textContent = mine.length + " total · " + mine.filter((p) => signState(p.id).live).length + " with live instant communication"; wire(); };
    const wire = () => { $$(".contact-row[data-cid]").forEach((r) => { const p = personX(r.dataset.cid); $(".nm", r).onclick = () => profilePopup(p); $(".avatar", r).onclick = () => profilePopup(p); $$("[data-sign]", r).forEach((b) => { b.onclick = () => { const sg = signState(p.id); sg[b.dataset.sign] = !sg[b.dataset.sign]; b.classList.toggle("on", sg[b.dataset.sign]); toast(b.title + (sg[b.dataset.sign] ? " given" : " removed") + " for " + p.name); paint(); }; b.oncontextmenu = (e) => { e.preventDefault(); hoursPopover(e.clientX, e.clientY, p, b.title); }; }); const a = $("[data-add]", r); if (a) a.onclick = () => toast("Demo: pick a group in Chats to add " + p.name + "."); const rm = $("[data-rm]", r); if (rm) rm.onclick = () => { S.contacts.delete(p.id); toast(p.name + " removed from your contacts"); paint(); }; const ac = $("[data-addc]", r); if (ac) ac.onclick = () => { S.contacts.add(p.id); toast(p.name + " added"); paint(); }; $$("[data-msg]", r).forEach((mg) => (mg.onclick = () => openDm(p.id))); r.ondblclick = () => openDm(p.id); }); };
    $("#cq").oninput = paint; paint();
  }

  // ---------------- MUSIC ----------------
  function cardAlbum(a) { return '<button class="card" data-al="' + esc(a.id) + '"><img class="art" src="' + esc(cov(a.cover)) + '" alt=""><div class="t">' + esc(a.title) + '</div><div class="a">' + esc(artist(a.artistId).name) + " · " + esc(a.year) + "</div></button>"; }
  function cardPl(p) { return '<button class="card" data-pl="' + esc(p.id) + '"><img class="art" src="' + esc(cov(p.cover)) + '" alt=""><div class="t">' + esc(p.name) + '</div><div class="a">' + p.trackIds.length + " tracks</div></button>"; }
  function trackRow(t, i) { const a = album(t.albumId); return '<button class="track-row" data-tr="' + esc(t.id) + '"><span class="idx">' + (i + 1) + '</span><span><div class="tt">' + esc(t.title) + '</div><div class="ta">' + esc(artist(t.artistId).name) + (a ? " · " + esc(a.title) : "") + '</div></span><span class="icon-btn shelf" data-shelf="' + esc(t.id) + '" title="Save to your shelf">' + icon(S.shelf.has(t.id) ? "check" : "shelf", 16) + '</span><span class="dur">' + esc(t.duration) + "</span></button>"; }
  function renderMusic() {
    const main = $("#main"); const M = D.music; let html = '<div class="page-pad page-wide">';
    const head = (eyebrow, title, sub) => '<div class="eyebrow">' + esc(eyebrow) + '</div><h1 class="display" style="font-size:32px;margin:0 0 6px">' + esc(title) + '</h1>' + (sub ? '<p class="muted" style="margin:0 0 18px">' + esc(sub) + "</p>" : "");
    const sub = musicSub;
    if (sub.kind === "home") {
      html += '<div style="display:flex;justify-content:space-between;gap:12px;align-items:flex-end;flex-wrap:wrap"><div>' + head("Music", "The Music Library", "Curated by the Kitaak Music team for " + D.company.name + " · " + PLAN_NAME) + '</div><div style="display:flex;gap:8px;margin-bottom:18px"><input class="input" id="mq" placeholder="Search songs, albums, artists" style="width:260px"><a class="btn sm" href="#/shelf">My shelf (' + S.shelf.size + ")</a></div></div>";
      const rec = M.albums.filter((a) => S.me.favoriteGenres.includes(a.genreId)).slice(0, 3);
      html += '<div class="hero" style="margin-bottom:8px"><img src="' + esc(cov((rec[0] || M.albums[0]).cover)) + '" style="width:220px;height:220px;border-radius:var(--r-lg);object-fit:cover"><div><div class="eyebrow">Kitaak recommendations for ' + esc(S.me.name.split(" ")[0]) + '</div><h2 class="display" style="font-size:26px;margin:6px 0">Picked for the genres you listen to most</h2><p class="muted">' + esc(S.me.favoriteGenres.map((g) => (genre(g) || {}).name).filter(Boolean).join(" · ")) + ' — based on your past music selections.</p><div style="display:flex;gap:8px;flex-wrap:wrap">' + rec.map((a) => '<button class="btn sm" data-al="' + esc(a.id) + '">' + icon("play", 14) + " " + esc(a.title) + "</button>").join("") + "</div></div></div>";
      M.sections.forEach((s) => { html += '<div class="section-head"><h3 style="margin:0">' + esc(s.title) + "</h3></div>"; if (s.kind === "albums") html += '<div class="hrow">' + s.itemIds.map(album).filter(Boolean).map(cardAlbum).join("") + "</div>"; else if (s.kind === "playlists") html += '<div class="hrow">' + s.itemIds.map(playlist).filter(Boolean).map(cardPl).join("") + "</div>"; else if (s.kind === "genres") html += '<div class="genre-grid">' + s.itemIds.map(genre).filter(Boolean).map((g) => '<button class="genre-tile" data-ge="' + esc(g.id) + '"><img src="' + esc(cov(g.cover)) + '" alt=""><b>' + esc(g.name) + "</b></button>").join("") + "</div>"; else if (s.kind === "tracks") html += '<div class="track-list">' + s.itemIds.map((id) => tracksById[id]).filter(Boolean).map(trackRow).join("") + "</div>"; });
      html += '<div class="section-head"><h3 style="margin:0">All genres</h3></div><div class="genre-grid">' + M.genres.map((g) => '<button class="genre-tile" data-ge="' + esc(g.id) + '"><img src="' + esc(cov(g.cover)) + '" alt=""><b>' + esc(g.name) + "</b></button>").join("") + "</div>";
    } else if (sub.kind === "album") { const a = album(sub.id); if (!a) { location.hash = "#/music"; return; } html += '<a class="back-link" href="#/music">' + icon("back", 14) + ' Music Library</a><div class="album-hero"><img src="' + esc(cov(a.cover)) + '" alt=""><div>' + head("Album · " + (genre(a.genreId) || {}).name, a.title, artist(a.artistId).name + " · " + a.year + " · " + a.tracks.length + " tracks") + '<div style="display:flex;gap:8px"><button class="btn primary" data-play-all="' + esc(a.id) + '">' + icon("play", 16) + ' Play</button><button class="btn" data-shelf-al="' + esc(a.id) + '">' + icon("shelf", 16) + ' Save to shelf</button><button class="btn" data-dl>' + icon("download", 16) + " Download</button></div></div></div><div class=\"track-list\">" + a.tracks.map((t, i) => trackRow(tracksById[t.id], i)).join("") + "</div>";
    } else if (sub.kind === "genre") { const g = genre(sub.id); if (!g) { location.hash = "#/music"; return; } const als = D.music.albums.filter((a) => a.genreId === g.id); html += '<a class="back-link" href="#/music">' + icon("back", 14) + ' Music Library</a>' + head("Genre", g.name, g.description) + '<div class="hrow" style="flex-wrap:wrap">' + als.map(cardAlbum).join("") + "</div>" + (als.length ? '<div class="section-head"><h3 style="margin:0">Tracks</h3></div><div class="track-list">' + als.flatMap((a) => a.tracks.map((t) => tracksById[t.id])).slice(0, 20).map(trackRow).join("") + "</div>" : "");
    } else if (sub.kind === "playlist") { const p = playlist(sub.id); if (!p) { location.hash = "#/music"; return; } html += '<a class="back-link" href="#/music">' + icon("back", 14) + ' Music Library</a><div class="album-hero"><img src="' + esc(cov(p.cover)) + '" alt=""><div>' + head("Playlist", p.name, p.description) + '<button class="btn primary" data-play-pl="' + esc(p.id) + '">' + icon("play", 16) + " Play</button></div></div><div class=\"track-list\">" + p.trackIds.map((id) => tracksById[id]).filter(Boolean).map(trackRow).join("") + "</div>";
    } else if (sub.kind === "shelf") { const ts = Array.from(S.shelf).map((id) => tracksById[id]).filter(Boolean); html += '<a class="back-link" href="#/music">' + icon("back", 14) + ' Music Library</a>' + head("My Music", "My shelf", ts.length ? ts.length + " saved songs — ready to download in the paid application." : "Save songs from any album or playlist; they show up here.") + '<div class="track-list">' + ts.map(trackRow).join("") + "</div>";
    } else if (sub.kind === "search") { const q = sub.q.toLowerCase(); const ts = Object.values(tracksById).filter((t) => (t.title + " " + artist(t.artistId).name).toLowerCase().includes(q)); const als = D.music.albums.filter((a) => (a.title + " " + artist(a.artistId).name).toLowerCase().includes(q)); html += '<a class="back-link" href="#/music">' + icon("back", 14) + ' Music Library</a>' + head("Search", '"' + sub.q + '"', als.length + " albums · " + ts.length + " songs") + (als.length ? '<div class="hrow">' + als.map(cardAlbum).join("") + "</div>" : "") + '<div class="track-list">' + ts.slice(0, 40).map(trackRow).join("") + "</div>"; }
    html += "</div>"; main.innerHTML = html;
    $$("[data-al]").forEach((b) => (b.onclick = () => (location.hash = "#/music/album/" + encodeURIComponent(b.dataset.al))));
    $$("[data-pl]").forEach((b) => (b.onclick = () => (location.hash = "#/music/playlist/" + encodeURIComponent(b.dataset.pl))));
    $$("[data-ge]").forEach((b) => (b.onclick = () => (location.hash = "#/music/genre/" + encodeURIComponent(b.dataset.ge))));
    $$("[data-tr]").forEach((b) => (b.onclick = (e) => { if (e.target.closest("[data-shelf]")) return; const t = tracksById[b.dataset.tr]; noMusicPopup(t.title + " — " + artist(t.artistId).name); }));
    $$("[data-shelf]").forEach((b) => (b.onclick = (e) => { e.stopPropagation(); const id = b.dataset.shelf; if (S.shelf.has(id)) S.shelf.delete(id); else S.shelf.add(id); b.innerHTML = icon(S.shelf.has(id) ? "check" : "shelf", 16); toast(S.shelf.has(id) ? "Saved to your shelf (demo)" : "Removed from your shelf"); }));
    $$("[data-play-all]").forEach((b) => (b.onclick = () => noMusicPopup(album(b.dataset.playAll).title)));
    $$("[data-play-pl]").forEach((b) => (b.onclick = () => noMusicPopup(playlist(b.dataset.playPl).name)));
    $$("[data-shelf-al]").forEach((b) => (b.onclick = () => { album(b.dataset.shelfAl).tracks.forEach((t) => S.shelf.add(t.id)); toast("Album saved to your shelf (demo)"); renderMusic(); }));
    $$("[data-dl]").forEach((b) => (b.onclick = () => toast("Demo: downloads need the paid application and a plan with downloads.")));
    const mq = $("#mq"); if (mq) mq.onkeydown = (e) => { if (e.key === "Enter" && mq.value.trim()) location.hash = "#/music/search?q=" + encodeURIComponent(mq.value.trim()); };
  }

  // ---------------- MY MUSIC ----------------
  function renderMyMusic() {
    const main = $("#main"); const shelf = Array.from(S.shelf).map((id) => tracksById[id]).filter(Boolean); const dl = Array.from(S.downloads).map((id) => tracksById[id]).filter(Boolean); const recent = S.recent.map((id) => tracksById[id]).filter(Boolean);
    const mine = [playlist("pl-commute")].concat(S.myPlaylists).filter(Boolean);
    main.innerHTML = '<div class="page-pad page-wide"><div style="display:flex;justify-content:space-between;align-items:flex-end;flex-wrap:wrap;gap:12px"><div><div class="eyebrow">My Music</div><h1 class="display" style="font-size:32px;margin:0 0 6px">Your shelf</h1><p class="muted" style="margin:0 0 18px">Songs you saved, playlists you made, what you downloaded and what you played last.</p></div><div style="display:flex;gap:8px;margin-bottom:18px"><a class="btn sm" href="#/music">' + icon("music", 14) + ' Music Library</a><button class="btn sm primary" id="newPl">' + icon("addplaylist", 14) + " New playlist</button></div></div>" +
      '<div class="section-head"><h3 style="margin:0">Saved songs</h3><span class="muted" style="font-size:12px">' + shelf.length + ' songs · ready to download in the paid application</span></div><div class="track-list">' + (shelf.map(trackRow).join("") || '<div class="muted">Save songs from any album or playlist; they show up here.</div>') + "</div>" +
      '<div class="section-head"><h3 style="margin:0">Your playlists</h3></div><div class="hrow">' + mine.map(cardPl).join("") + "</div>" +
      '<div class="section-head"><h3 style="margin:0">Downloads</h3><span class="muted" style="font-size:12px">kept on this device for offline listening</span></div><div class="track-list">' + dl.map(trackRow).join("") + "</div>" +
      '<div class="section-head"><h3 style="margin:0">Recently played</h3></div><div class="track-list">' + recent.map(trackRow).join("") + "</div></div>";
    $$("[data-pl]").forEach((b) => (b.onclick = () => { const p = S.myPlaylists.find((x) => x.id === b.dataset.pl); if (p) { noMusicPopup(p.name); return; } location.hash = "#/music/playlist/" + encodeURIComponent(b.dataset.pl); }));
    $$("[data-tr]").forEach((b) => (b.onclick = (e) => { if (e.target.closest("[data-shelf]")) return; const t = tracksById[b.dataset.tr]; noMusicPopup(t.title + " — " + artist(t.artistId).name); }));
    $$("[data-shelf]").forEach((b) => (b.onclick = (e) => { e.stopPropagation(); const id = b.dataset.shelf; if (S.shelf.has(id)) S.shelf.delete(id); else S.shelf.add(id); renderMyMusic(); toast(S.shelf.has(id) ? "Saved to your shelf (demo)" : "Removed from your shelf"); }));
    $("#newPl").onclick = () => modal("New playlist", '<div class="field"><label class="sr-title">Name</label><input class="input" id="plName" placeholder="e.g. Hangar mornings"></div>', [{ label: "Cancel" }, { label: "Create", cls: "primary", onClick: () => { const n = ($("#plName").value || "").trim(); if (!n) return false; S.myPlaylists.push({ id: "pl-mine-" + uid(), name: n, description: "Made by you", cover: D.music.playlists[1].cover, trackIds: [] }); renderMyMusic(); toast("Playlist created (demo)"); } }]);
  }

  // ---------------- CORPORATE MUSIC (the application's /company-music page) ----------------
  function renderCompanyMusic(tab) {
    const main = $("#main"); const c = D.company;
    const tabs = '<div class="seg" style="margin:14px 0 18px"><button class="' + (tab === "playlists" ? "on" : "") + '" data-tab="playlists">Top playlists</button><button class="' + (tab === "music" ? "on" : "") + '" data-tab="music">Everyone\'s songs</button><button class="' + (tab === "blog" ? "on" : "") + '" data-tab="blog">Company blog</button></div>';
    let body = "";
    if (tab === "playlists") {
      const ranked = D.music.playlists.slice().sort((a, b) => S.points[b.id] - S.points[a.id]);
      body = '<div class="eyebrow" style="margin-bottom:8px">Shared playlists — ranked by points</div><div class="cm-grid">' + ranked.map((p, i) => { const owner = S.people[(i * 5) % S.people.length]; return '<div class="panel cm-card"><div style="display:flex;gap:12px"><img src="' + esc(cov(p.cover)) + '" style="width:84px;height:84px;border-radius:12px;object-fit:cover" alt=""><div style="min-width:0;flex:1"><div class="eyebrow">#' + (i + 1) + '</div><div class="sr-title" style="font-size:16px">' + esc(p.name) + '</div><div class="sr-desc">' + esc(p.description) + '</div><div class="muted" style="font-size:12px;margin-top:4px">shared by ' + esc(owner.name) + " · " + p.trackIds.length + " tracks</div></div></div><div style=\"display:flex;gap:8px;align-items:center;margin-top:10px;flex-wrap:wrap\"><button class=\"btn sm primary\" data-pt=\"" + esc(p.id) + '">' + icon("heart", 14) + ' Give a point</button><span class="chip">' + S.points[p.id] + ' points</span><button class="btn sm" data-open-pl="' + esc(p.id) + '">' + icon("play", 14) + ' Open</button><button class="btn sm ghost" data-cm="' + esc(p.id) + '">' + icon("chat", 14) + " Comment (" + (S.comments[p.id] || []).length + ")</button></div>" + ((S.comments[p.id] || []).length ? '<div style="margin-top:8px;font-size:13px">' + S.comments[p.id].map((x) => "<div><b>" + esc(x.who) + ":</b> " + esc(x.text) + "</div>").join("") + "</div>" : "") + "</div>"; }).join("") + "</div>";
    } else if (tab === "music") {
      body = '<input class="input" id="cmq" placeholder="Search people, songs, artists, albums…" style="max-width:420px;margin-bottom:14px"><div class="cm-grid" id="cmPeople"></div>';
    } else {
      body = '<div class="stack" style="max-width:760px">' + D.announcements.map((a) => '<div class="panel"><div class="eyebrow">' + esc(nameOf(a.fromId)) + " · " + a.daysAgo + ' days ago</div><div class="sr-title" style="font-size:17px;margin:4px 0">' + esc(a.title) + '</div><div class="muted" style="font-size:14px">' + esc(a.body) + "</div></div>").join("") + '<div class="panel"><div class="sr-title">Write a post</div><textarea class="input" id="blogIn" rows="3" placeholder="Share news with the company…"></textarea><div style="margin-top:8px"><button class="btn sm primary" id="blogPost">Post</button></div></div></div>';
    }
    main.innerHTML = '<div class="page-pad page-wide"><div class="eyebrow">' + esc(c.name) + '</div><h1 class="display" style="font-size:32px;margin:0 0 6px">Corporate Music</h1><p class="muted" style="margin:0">Share playlists, songs and albums with your colleagues, comment on each other\'s picks, and give points — the most-pointed playlists rise to the top.</p><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px"><span class="chip">' + PLAN_NAME + '</span><span class="chip">workplace music: Kitaak Music Library</span><a class="chip" href="#/company">' + icon("briefcase", 13) + " Company profile</a></div>" + tabs + body + "</div>";
    $$("[data-tab]").forEach((b) => (b.onclick = () => (location.hash = "#/company-music/" + b.dataset.tab)));
    $$("[data-pt]").forEach((b) => (b.onclick = () => { S.points[b.dataset.pt]++; toast("Point given (demo)"); renderCompanyMusic("playlists"); }));
    $$("[data-open-pl]").forEach((b) => (b.onclick = () => (location.hash = "#/music/playlist/" + encodeURIComponent(b.dataset.openPl))));
    $$("[data-cm]").forEach((b) => (b.onclick = () => { const id = b.dataset.cm; const m = modal("Comment on " + playlist(id).name, '<textarea class="input" id="cmText" rows="3" placeholder="Say something nice about this playlist"></textarea>', [{ label: "Cancel" }, { label: "Post comment", cls: "primary", onClick: () => { const t = $("#cmText").value.trim(); if (!t) return false; (S.comments[id] = S.comments[id] || []).push({ who: S.me.name, text: t }); renderCompanyMusic("playlists"); } }]); }));
    if (tab === "music") {
      const paint = () => { const q = ($("#cmq").value || "").trim().toLowerCase(); const ppl = [S.me].concat(S.people).map((p) => ({ p, favs: favsOf(p.id) })).filter((x) => !q || x.p.name.toLowerCase().includes(q) || x.favs.some((t) => (t.title + " " + artist(t.artistId).name + " " + (album(t.albumId) || {}).title).toLowerCase().includes(q))); $("#cmPeople").innerHTML = ppl.map((x) => '<div class="panel cm-card"><div style="display:flex;gap:10px;align-items:center">' + avatar(x.p, 30, true) + '<div style="min-width:0"><div class="sr-title">' + esc(x.p.name) + (x.p.id === "allison" ? " (you)" : "") + '</div><div class="sr-desc">' + x.favs.length + " shared song" + (x.favs.length === 1 ? "" : "s") + '</div></div></div><div class="track-list" style="margin-top:8px">' + x.favs.slice(0, 5).map((t, i) => trackRow(t, i)).join("") + "</div></div>").join("") || '<div class="muted" style="text-align:center;padding:24px">No matches for “' + esc(q) + '”.</div>'; $$("[data-tr]").forEach((b) => (b.onclick = (e) => { if (e.target.closest("[data-shelf]")) return; const t = tracksById[b.dataset.tr]; noMusicPopup(t.title + " — " + artist(t.artistId).name); })); $$("[data-shelf]").forEach((b) => (b.onclick = (e) => { e.stopPropagation(); const id = b.dataset.shelf; if (S.shelf.has(id)) S.shelf.delete(id); else S.shelf.add(id); b.innerHTML = icon(S.shelf.has(id) ? "check" : "shelf", 16); toast(S.shelf.has(id) ? "Saved to your shelf (demo)" : "Removed from your shelf"); })); };
      $("#cmq").oninput = paint; paint();
    }
    if (tab === "blog") $("#blogPost").onclick = () => { const t = $("#blogIn").value.trim(); if (!t) return; D.announcements.unshift({ id: uid(), title: t.slice(0, 60), body: t, fromId: "allison", daysAgo: 0 }); renderCompanyMusic("blog"); toast("Posted to the company blog (demo)"); };
  }

  // ---------------- SEARCH (tabs: Music is highlighted first; pick one or more) ----------------
  const SEARCH_TABS = [["music", "Music"], ["messages", "Messages"], ["people", "People"]];
  let searchSel = ["music"];
  function renderSearch(q) {
    const main = $("#main"); main.innerHTML = '<div class="page-pad page-wide"><div class="eyebrow">Search</div><h1 class="display" style="font-size:32px;margin:0 0 12px">Search</h1><div class="search-tabs" id="stabs"></div><input class="input" id="sq" placeholder="Songs, albums, artists…" value="' + esc(q) + '" style="max-width:560px" autofocus><div id="sres" style="margin-top:18px"></div></div>';
    const paintTabs = () => { $("#stabs").innerHTML = SEARCH_TABS.map(([k, l]) => '<button class="chip ' + (searchSel.includes(k) ? "on" : "") + '" data-st="' + k + '">' + l + "</button>").join(""); $$("[data-st]").forEach((b) => (b.onclick = () => { const k = b.dataset.st; searchSel = searchSel.includes(k) ? (searchSel.length > 1 ? searchSel.filter((x) => x !== k) : searchSel) : searchSel.concat([k]); paintTabs(); paint(); })); $("#sq").placeholder = searchSel.length === 1 ? { music: "Songs, albums, artists…", messages: "Words in your chats…", people: "Names, titles, departments…" }[searchSel[0]] : "People, messages, songs, albums…"; };
    const paint = () => { const qq = $("#sq").value.trim().toLowerCase(); const out = $("#sres"); if (!qq) { out.innerHTML = '<div class="muted">Type to search ' + searchSel.map((k) => ({ music: Object.keys(tracksById).length + " songs and " + D.music.albums.length + " albums", messages: S.rooms.reduce((n, r) => n + r.messages.length, 0) + " messages", people: S.people.length + " people" }[k])).join(", ") + ". Select one or more tabs above.</div>"; return; }
      let html = "";
      if (searchSel.includes("music")) { const ts = Object.values(tracksById).filter((t) => (t.title + " " + artist(t.artistId).name + " " + (album(t.albumId) || {}).title).toLowerCase().includes(qq)).slice(0, 12); const als = D.music.albums.filter((a) => (a.title + " " + artist(a.artistId).name).toLowerCase().includes(qq)); html += '<div class="section-head" style="margin-top:0"><h3 style="margin:0">Music</h3><span class="muted" style="font-size:12px">' + als.length + " albums · " + ts.length + ' songs</span></div>' + (als.length ? '<div class="hrow">' + als.map(cardAlbum).join("") + "</div>" : "") + (ts.length ? '<div class="track-list">' + ts.map(trackRow).join("") + "</div>" : (als.length ? "" : '<div class="muted">No music matches.</div>')); }
      if (searchSel.includes("messages")) { const msgs = []; S.rooms.forEach((r) => r.messages.forEach((m) => { if (m.text && m.text.toLowerCase().includes(qq)) msgs.push({ r, m }); })); html += '<div class="section-head"><h3 style="margin:0">Messages</h3><span class="muted" style="font-size:12px">' + msgs.length + "</span></div>" + (msgs.slice(0, 12).map(({ r, m }) => '<div class="contact-row" data-r="' + esc(r.id) + '" style="cursor:pointer;grid-template-columns:1fr auto"><div><div class="nm" style="font-size:13px">' + esc(roomTitle(r)) + ' · <span class="muted">' + esc(nameOf(m.from)) + '</span></div><div class="sub">' + esc(m.text.slice(0, 120)) + '</div></div><span class="conv-time">' + fmtConv(m.at) + "</span></div>").join("") || '<div class="muted">No messages match.</div>'); }
      if (searchSel.includes("people")) { const ppl = S.people.filter((p) => (p.name + " " + p.title + " " + p.department).toLowerCase().includes(qq)).slice(0, 10); html += '<div class="section-head"><h3 style="margin:0">People</h3><span class="muted" style="font-size:12px">' + ppl.length + "</span></div>" + (ppl.map((p) => '<div class="contact-row" data-p="' + esc(p.id) + '" style="cursor:pointer">' + avatar(p, 40, true) + '<div><div class="nm">' + esc(p.name) + '</div><div class="sub">' + esc(p.title) + " · " + esc(p.department) + "</div></div><div></div></div>").join("") || '<div class="muted">Nobody matches.</div>'); }
      out.innerHTML = html;
      $$("[data-p]", out).forEach((e) => (e.onclick = () => profilePopup(personX(e.dataset.p)))); $$("[data-r]", out).forEach((e) => (e.onclick = () => (location.hash = "#/chat/" + encodeURIComponent(e.dataset.r)))); $$("[data-al]", out).forEach((b) => (b.onclick = () => (location.hash = "#/music/album/" + encodeURIComponent(b.dataset.al)))); $$("[data-tr]", out).forEach((b) => (b.onclick = (e) => { if (e.target.closest("[data-shelf]")) return; const t = tracksById[b.dataset.tr]; noMusicPopup(t.title + " — " + artist(t.artistId).name); })); $$("[data-shelf]", out).forEach((b) => (b.onclick = (e) => { e.stopPropagation(); const id = b.dataset.shelf; if (S.shelf.has(id)) S.shelf.delete(id); else S.shelf.add(id); b.innerHTML = icon(S.shelf.has(id) ? "check" : "shelf", 16); }));
    };
    paintTabs(); $("#sq").oninput = paint; paint(); $("#sq").focus();
  }

