        row("Who Can Be Heard Over the Music", "Choose which groups can speak over your music. You can select multiple groups, such as Company and Contacts. <b>Selection</b> includes contacts with <b>Live Comm</b> access. Choose <b>Nobody</b> for uninterrupted music.", "", 'style="flex-wrap:wrap"').replace("</div></div>", "</div>" + chips([["everyone", "Everyone"], ["contacts", "Contacts"], ["company", "Company"], ["selection", "Selection"], ["nobody", "Nobody"]], (v) => st.heardOver.includes(v), 'id="heardOver"') + "</div>") +
        row("Activate microphone when I speak", "Voice‑activated — the mic opens automatically when you start talking.", sw(st.micVox, 'data-s="micVox"')) +
        row("Hands‑Free 10‑Second Reply Window", "After either person finishes speaking, both microphones remain active for about 10 seconds so either person can reply without restarting the conversation. Ideal for hands‑free use with a headset. Tap <b>Voice</b> button to end this function before 10 seconds.", sw(st.handsFree, 'data-s="handsFree"')) +
        '<div class="faint" style="font-size:11.5px;margin-top:8px">Set per‑person priority in a chat (group members / open DM) or in Contacts. Host always has override priority.</div></div>' +
      '<div class="panel"><h3>' + icon("lock", 16) + ' Security</h3>' + row("App lock", 'Require a PIN when opening Kitaak on this account. Set the PIN when turning it on; "Lock now" locks immediately.', '<span style="display:flex;gap:6px;align-items:center">' + (st.appLock ? '<button class="btn ghost sm" id="lockNow">Lock now</button>' : "") + sw(st.appLock, 'data-s="appLock"') + "</span>") + row("Two‑factor authentication", "A second step at login from your authenticator app (TOTP). Turning it on walks you through setup immediately.", sw(st.twoFactor, 'data-s="twoFactor"')) + row("Encrypt local data", "Encrypt cached messages & files on this device.", sw(st.encrypt, 'data-s="encrypt"')) + row("Back up & restore on this device", "Download a JSON backup of your data, or upload one to restore your settings, library, playlists and contacts.", '<span style="display:flex;gap:6px"><button class="btn sm" id="bkBtn">' + icon("download", 14) + ' Back up</button><button class="btn sm" id="rsBtn">' + icon("upload", 14) + " Restore</button></span>") + row("Reset App & Clear My Data", "Permanently deletes your messages, conversations, files, music, playlists, downloads, saved songs, and contacts, and resets all preferences to their defaults. Your account, sign‑in status, memberships, and other people's messages in shared channels are retained. This action cannot be undone.", '<button class="btn sm danger" id="resetBtn2">' + icon("trash", 14) + " Reset & clear</button>") + '<div class="faint" style="font-size:11.5px;margin-top:8px">Server also enforces password hashing, JWT sessions, security headers, and login rate‑limiting. End‑to‑end encryption is on the roadmap.</div></div>' +
      '<div class="panel"><h3>' + icon("membercard", 16) + ' Billing</h3>' + row(esc(c.name) + " Corporate Account", "Your membership is covered by your company — there is no personal bill for this account.", '<a class="btn sm" href="#/membership">Membership</a>') + "</div>" +
      '<div class="panel"><h3>' + icon("lock", 16) + ' Privacy & Blocklist</h3>' + row("Who can reach you, last‑seen, read receipts, blocked people", "Manage all privacy controls (incl. corporate members).", '<a class="btn sm" href="#/settings/privacy">Open</a>') + "</div>" +
      '<button class="instructions-fab" id="instrBtn">' + icon("file", 14) + " Instructions</button></div>";
    wireThemes(main);
