    const ln = $("#lockNow"); if (ln) ln.onclick = () => modal("Locked", '<p>Kitaak is locked. Enter your PIN to continue.</p><input class="input" type="password" placeholder="PIN" style="max-width:160px">', [{ label: "Unlock", cls: "primary" }]);
