      '<div class="panel"><h3>Identity</h3><div class="panel-sub">Private unless you check <b>Public\'s</b> — then it shows on your profile popup.</div>' +
        '<div class="setting-row" style="flex-wrap:wrap"><div class="sr-main" style="min-width:160px"><div class="sr-title">Date Of Birth</div><input class="input" type="date" id="dobIn" value="' + esc(me.dob) + '" style="max-width:200px;margin-top:4px"></div><label class="chip"><input type="checkbox" data-pub="dob" ' + (me.pub.dob ? "checked" : "") + "> Public</label></div>" +
        '<div class="setting-row" style="flex-wrap:wrap"><div class="sr-main" style="min-width:160px"><div class="sr-title">Location</div><div class="sr-desc">City, state & country</div><div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:4px"><input class="input" placeholder="City" data-f="city" value="' + esc(me.city || "") + '" style="max-width:160px"><input class="input" placeholder="State" data-f="state" value="' + esc(me.state || "") + '" style="max-width:120px"><input class="input" placeholder="Country" data-f="country" value="' + esc(me.country || "") + '" style="max-width:160px"></div></div><label class="chip"><input type="checkbox" data-pub="location" ' + (me.pub.location ? "checked" : "") + "> Public</label></div>" +
        row("Title & department", "Shown on your profile popup and in the corporate directory.", '<span style="display:flex;gap:6px;flex-wrap:wrap"><input class="input" data-f="title" value="' + esc(me.title || "") + '" style="max-width:200px"><input class="input" data-f="department" value="' + esc(me.department || "") + '" style="max-width:180px"></span>', 'style="flex-wrap:wrap"') +
        row("Bio", "One line about you.", '<input class="input" data-f="bio" value="' + esc(me.bio || "") + '" style="max-width:360px">', 'style="flex-wrap:wrap"') +
        '<div style="margin-top:10px"><button class="btn primary sm" id="saveProf">Save profile</button></div></div>' +
      '<div class="panel"><h3 style="color:var(--danger)">Sensitive Functions</h3>' + row("Deactivate Account", "Temporarily hide your account. Log back in any time to reactivate — nothing is deleted.", '<button class="btn sm" id="deactBtn">Deactivate</button>') + row("Delete Profile", "Permanently delete your profile and data. This can't be undone.", '<button class="btn danger sm" id="delProfile2">Delete</button>') + "</div></div>";
    wireThemes(main);
    $$("[data-s]", main).forEach((el) => wireSwitch(el, (on) => { S.settings[el.dataset.s] = on; renderProfile(); }));
