    $("#cancelMem").onclick = () => modal("Cancel membership", "<p>Your membership is covered by " + esc(D.company.name) + ". Cancellation is handled by your company administrator on the Corporate page.</p>", [{ label: "Close", cls: "primary" }]);
    $("#saveProf").onclick = () => { me.name = $("#nameIn").value.trim() || me.name; me.dob = $("#dobIn").value; $$("[data-f]").forEach((i) => (me[i.dataset.f] = i.value.trim())); $$("[data-pub]").forEach((c) => (me.pub[c.dataset.pub] = c.checked)); me.initials = initials(me.name); $("#bannerWho").textContent = "Signed in as " + me.name; renderNav(); renderProfile(); toast("Profile saved (demo — not stored anywhere)"); };
